/*
 * A357075  Numbers sandwiched between numbers with exactly three distinct
 *          prime factors.
 * https://oeis.org/A357075
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, easy
 * Formula:   not stated
 * Range:     u8 n <= 8, u16 n <= 54, u32 n <= 54, u64 n <= 54, u128 n <= 54,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* Search for the n‑th integer k such that both k-1 and k+1
 * have exactly three distinct prime factors.  The sequence
 * A357075 is generated by sieving the number of distinct prime
 * factors (omega) of each integer as needed.
 *
 * The implementation maintains a global cache of the sequence
 * and grows both the prime‑factor table and the sequence array
 * on demand.  It is written to compile in C11 and C++17
 * by casting the result of malloc/realloc to the appropriate
 * pointer type.
 */

#include <stdlib.h>
#include <stddef.h>
#include <stdint.h>
#include <stdbool.h>

/* Array holding the number of distinct prime factors (omega) for each integer.
 * omega[i] == 0 for i less than the first prime (2).  We treat 0 and 1 as having omega 0. */
static uint8_t *omega = NULL;          /* dynamic array of uint8_t */
static idx_t omega_cap = 0;            /* capacity of omega array */

/* Ensure that omega is computed up to at least 'up_to' (inclusive). */
static void ensure_omega(idx_t up_to)
{
    if (up_to <= omega_cap)
        return;

    idx_t new_cap = omega_cap ? omega_cap * 2 : up_to;
    if (new_cap < up_to)
        new_cap = up_to;

    /* Allocate a zeroed buffer.  The cast is required for C++ compiles. */
    uint8_t *new_omega = (uint8_t *)calloc((size_t)new_cap + 1, sizeof(uint8_t));
    if (!new_omega)
        abort();

    /* Compute omega values up to new_cap by a simple sieve. */
    for (idx_t i = 2; i <= new_cap; ++i) {
        if (new_omega[i] == 0) {               /* i is prime */
            for (idx_t j = i; j <= new_cap; j += i)
                ++new_omega[j];
        }
    }

    /* Replace the old array. */
    free(omega);
    omega = new_omega;
    omega_cap = new_cap;
}

/* Dynamic array for the sequence values. */
static seq_t *seq = NULL;          /* array of seq_t */
static size_t seq_len = 0;         /* number of elements stored */
static size_t seq_cap = 0;         /* current capacity of seq array */
static idx_t next_candidate = 2;   /* next integer to test */

/* Extend the stored sequence until it contains at least 'target' elements. */
static void generate_until(idx_t target)
{
    while (seq_len < target) {
        /* Need omega for next_candidate-1 and next_candidate+1. */
        ensure_omega(next_candidate + 1);

        if (next_candidate >= 2) {
            if (omega[next_candidate - 1] == 3 && omega[next_candidate + 1] == 3) {
                /* Grow the sequence array if necessary. */
                if (seq_len == seq_cap) {
                    seq_cap = seq_cap ? seq_cap * 2 : 16;
                    seq = (seq_t *)realloc(seq,
                                            seq_cap * sizeof(seq_t));
                    if (!seq)
                        abort();
                }
                seq[seq_len++] = next_candidate;
            }
        }
        ++next_candidate;
    }
}

/* Public sequence function required by the harness. */
seq_t a(idx_t n)
{
    if (n == 0)
        return (seq_t)0;          /* Not part of the sequence; fallback. */
    generate_until(n);
    return seq[n - 1];
}
